<script setup lang="ts">
/**
 * Modal interruption of the page (`design/components/dialog.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/dialog.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import {
  cloneVNode,
  computed,
  inject,
  onBeforeUnmount,
  onMounted,
  provide,
  ref,
  useId,
  useTemplateRef,
  watch,
} from 'vue'

import * as zag from '@zag-js/dialog'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  agentMember,
  definedProps,
  focusPlace,
  focusReturnTarget,
  modalFocusTarget,
  slottedElements,
  useDirection,
  useMediaQuery,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/overlays/dialog.module.css'
import Button from '../controls/Button.vue'

export interface DialogProps {
  /**
   * Uses `alertdialog` rather than `dialog`, for an interruption the reader must answer.
   * ConfirmDialog sets it for its danger tone.
   */
  alert?: boolean
  closeLabel?: string
  defaultOpen?: boolean
  description?: string
  /**
   * `false` removes ✕ and ignores Escape and outside clicks, forcing a choice.
   */
  dismissible?: boolean
  /**
   * Which footer control has focus on open; `dismiss` suits a panel that asks whether you meant
   * it (see `initialFocus`).
   */
  initialFocus?: 'primary' | 'dismiss'
  open?: boolean
  /**
   * `'auto'` is the card, and the whole screen below `30rem` (the overlay class's viewport
   * exemption). `'sheet'` keeps the card above `30rem` and becomes a bottom sheet below it (the
   * sheet presentation, `design/components/README.md`). It is for content-light confirm and pick
   * dialogs, where a full-screen takeover is too heavy. Only the shape changes: scrim, trap,
   * `dismissible`, initial focus and return focus are Dialog's in both forms, which is why it
   * can be a prop.
   */
  presentation?: 'auto' | 'sheet'
  size?: 'sm' | 'md' | 'lg'
  title: string
}

defineOptions({ name: 'Dialog', inheritAttrs: false })

const props = withDefaults(defineProps<DialogProps>(), {
  alert: false,
  closeLabel: 'Close',
  defaultOpen: undefined,
  dismissible: true,
  initialFocus: 'primary',
  open: undefined,
  presentation: 'auto',
  size: 'md',
})
const emit = defineEmits<{ openChange: [open: boolean] }>()
defineSlots<{
  default?: (props: Record<string, never>) => unknown
  footer?: (props: Record<string, never>) => unknown
  trigger?: (props: Record<string, never>) => unknown
}>()
const uid = useId()
const lent = inject<string | undefined>('polymorph:identity', undefined)
const lender = inject<{ element?: () => Element | null | undefined } | undefined>(
  'polymorph:borrowed',
  undefined,
)
provide('polymorph:borrowed', undefined)
const pressed = ref(null as HTMLElement | null)
const returnTo = ref(null as ReturnType<typeof focusPlace>)
const panel = useTemplateRef<HTMLElement>('panel')
const scrim = useTemplateRef<HTMLElement>('scrim')
const phone = useMediaQuery('phone')
const sheet = computed(() => props.presentation === 'sheet' && phone.value)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    open: props.open,
    defaultOpen: props.defaultOpen,
    role: props.alert ? 'alertdialog' : 'dialog',
    closeOnEscape: props.dismissible,
    closeOnInteractOutside: props.dismissible,
    initialFocusEl: () => modalFocusTarget(panel.value, props.initialFocus),
    finalFocusEl: () => focusReturnTarget(returnTo.value, [panel.value]),
    onOpenChange: (details) => {
      emit('openChange', details.open)
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const openFrom = computed(() => (event?: Event) => {
  if (event?.currentTarget instanceof HTMLElement) pressed.value = event.currentTarget
  api.value.setOpen(true)
})
const scrimPresent = usePresence(() => api.value.open, scrim, 'dialog.scrim')
const panelPresent = usePresence(
  () => api.value.open,
  panel,
  () => (sheet.value ? 'sheet.panel' : 'dialog.panel'),
  { sheetSide: 'bottom' },
)
const effect1 = () => {
  lender && (lender.element = () => panel.value)
}
onMounted(effect1)
const effect2 = () => {
  api.value.open &&
    ((returnTo.value = focusPlace(pressed.value ?? document.activeElement)), (pressed.value = null))
}
onMounted(effect2)
watch(() => api.value.open, effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = lender
    ? () => {}
    : agentMember({
        member: 'Dialog',
        element: () => panel.value,
        state: () => ({ open: api.value.open }),
        actions: {
          close: () =>
            (() => {
              if (!props.dismissible)
                throw new Error('The dialog asks for a choice among its own actions.')
              api.value.setOpen(false)
            })(),
        },
      })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <template v-for="(node, at) in slottedElements($slots.trigger)" :key="at">
    <component :is="cloneVNode(node, definedProps({ onClick: openFrom }))" />
  </template>
  <Teleport to="body">
    <!-- scrim -->
    <div
      v-if="scrimPresent"
      ref="scrim"
      v-bind="api.getBackdropProps()"
      :class="styles.scrim"
      :hidden="undefined"
    />
    <div
      v-if="panelPresent"
      v-bind="api.getPositionerProps()"
      :class="[sheet ? styles.sheetPositioner : undefined, !sheet ? styles.positioner : undefined]"
    >
      <!-- panel -->
      <div
        ref="panel"
        v-bind="api.getContentProps()"
        :class="[sheet ? styles.sheetPanel : undefined, !sheet ? styles.panel : undefined]"
        :hidden="undefined"
        :data-presentation="sheet ? 'sheet' : undefined"
        :data-size="size"
        :data-member="lent ?? 'dialog'"
      >
        <!-- title -->
        <h2 v-bind="api.getTitleProps()" :class="styles.title">
          {{ title }}
        </h2>
        <!-- description -->
        <p
          v-if="description !== undefined"
          v-bind="api.getDescriptionProps()"
          :class="styles.description"
        >
          {{ description }}
        </p>
        <!-- body -->
        <div :class="styles.body" data-dialog-part="body">
          <slot />
        </div>
        <!-- footer -->
        <div v-if="$slots.footer" :class="styles.footer" data-dialog-part="footer">
          <slot name="footer" />
        </div>
        <!-- close -->
        <div v-if="dismissible" :class="styles.close" data-dialog-part="close">
          <Button
            variant="ghost"
            tone="neutral"
            size="sm"
            :iconOnly="true"
            icon="close"
            :label="closeLabel"
            @click="api.setOpen(false)"
          />
        </div>
      </div>
    </div>
  </Teleport>
</template>
